import com.github.tartaricacid.touhoulittlemaid.compat.gun.swarfare.SWarfareCompat;
import javax.annotation.Nullable;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;
import net.minecraftforge.registries.ForgeRegistries;

@OnlyIn(value=Dist.CLIENT)
public class GunBaseAnimation {
    public static boolean onHoldGun(IMaid maid, @Nullable ModelRendererWrapper armLeft, @Nullable ModelRendererWrapper armRight) {
        Mob mob = maid.asEntity();
        if (mob == null) {
            return false;
        }
        ItemStack handItem = mob.m_21205_();
        if (!(handItem.m_41720_() instanceof GunItem)) {
            return false;
        }
        ResourceLocation gunId = ForgeRegistries.ITEMS.getKey((Object)handItem.m_41720_());
        if (gunId == null) {
            return false;
        }
        if (gunId.equals((Object)SWarfareCompat.MINIGUN_ID) || gunId.equals((Object)SWarfareCompat.M_2_HB_ID)) {
            if (armLeft != null) {
                armLeft.setRotateAngleX(-1.45f);
                armLeft.setRotateAngleY(1.0f);
            }
            if (armRight != null) {
                armRight.setRotateAngleX(0.75f);
                armRight.setRotateAngleY(0.0f);
            }
            return true;
        }
        if (armLeft != null) {
            armLeft.setRotateAngleX(-1.75f);
            armLeft.setRotateAngleY(0.5f);
        }
        if (armRight != null) {
            armRight.setRotateAngleX(-1.65f);
            armRight.setRotateAngleY(-0.174f);
        }
        return true;
    }
}

